CREATE PROCEDURE SP_ConsQuery1 (@Ordid int,@Styleno Varchar(30),@Coycode int,@StageID int)
AS 

SELECT Prog_ClrComb.Yd, Prog_ClrComb.compID, Prog_ClrComb.ID, Prog_ClrComb.ClrCombID, Prog_ClrComb.FabClr, Prog_ClrComb.FabDesc, Prog_ClrComb.GreyGsm, Prog_ClrComb.FinalGsm, Prog_ClrComb.GG, Prog_ClrComb.LL, Prog_Cns.FABWIDTH AS FabWid, Prog_ClrComb.WtUom, Prog_ClrComb.LooseFab, Prog_Cns.sizid, Prog_Cns.Actpcswgt, Prog_Cns.kdia, Prog_Cns.fdia, Prog_Cns.ldia, Sum(Trs_ProdentryQty.ProdPcs) AS OrderQty, 0 AS Exs_Per, Prog_ClrComb.CompGrdSlno,  Prog_ClrComb.PExc, ISNULL(Prog_Cns.NoofPiece, 1) AS NoofPiece, ISNULL(OrderQtyDtl.CutPlanQty, 0)AS CutPlanQty FROM Prog_ClrComb INNER JOIN Prog_Cns ON Prog_ClrComb.ID = Prog_Cns.ID INNER JOIN OrderQtyDtl ON Prog_ClrComb.OrdID = OrderQtyDtl.OrdID AND Prog_ClrComb.StyleNo = OrderQtyDtl.StyleNo AND Prog_Cns.sizid = OrderQtyDtl.SizeId AND Prog_ClrComb.ClrCombID = OrderQtyDtl.ColID  inner join Trs_Prodentry on Trs_Prodentry .ordid =OrderQtyDtl.OrdID  AND Trs_Prodentry.StyleNo = OrderQtyDtl.StyleNo and Trs_Prodentry.clrid = OrderQtyDtl.ColID  inner join Trs_ProdentryQty on Trs_Prodentry.id=Trs_ProdentryQty.id and Trs_ProdentryQty.Sizid = OrderQtyDtl.SizeId   LEFT OUTER JOIN Prog_Component ON Prog_ClrComb.OrdID = Prog_Component.OrdID AND Prog_ClrComb.StyleNo = Prog_Component.StyleNo AND Prog_ClrComb.compID = Prog_Component.CompID AND Prog_ClrComb.ID = Prog_Component.sl INNER JOIN  (Select Distinct A.Ordid,A.Styleno,Stocktable.FabId,StockTable.Colid,StockTable.gsm,stocktable.fingsm,stocktable.gg,stocktable.ll From TRS_Del2 A  INNER JOIN Trs_Del1 B ON A.ID = B.ID  INNER JOIN StockTable ON Stocktable.Stockid = A.StockId Where TrType = -2 and Prs_Dept=11  and stocktable.YF='F' ) X ON X.FabID = Prog_ClrComb.FabDesc And X.colid = prog_clrcomb.fabclr And X.gsm = Prog_ClrComb.GreyGsm And X.FinGsm = Prog_ClrComb.FinalGsm and X.GG = Prog_ClrComb.GG  And X.LL = Prog_ClrComb.LL and X.ordid = OrderQtyDtl.Ordid and x.styleno = OrderQtyDtl.Styleno   WHERE     (Prog_ClrComb.OrdID = @OrdId) AND (Prog_ClrComb.StyleNo =  @StyleNo) and Trs_Prodentry.stageid=@StageId and Trs_Prodentry.coyid=@Coycode and Prog_ClrComb.yd <> 1 group by Prog_ClrComb.Yd, Prog_ClrComb.compID, Prog_ClrComb.ID, Prog_ClrComb.ClrCombID, Prog_ClrComb.FabClr, Prog_ClrComb.FabDesc, Prog_ClrComb.GreyGsm, Prog_ClrComb.FinalGsm, Prog_ClrComb.GG, Prog_ClrComb.LL, Prog_Cns.FABWIDTH , Prog_ClrComb.WtUom, Prog_ClrComb.LooseFab, Prog_Cns.sizid, Prog_Cns.Actpcswgt, Prog_Cns.kdia, Prog_Cns.fdia, Prog_Cns.ldia,  Prog_ClrComb.CompGrdSlno, Prog_ClrComb.PExc,OrderQtyDtl.CutPlanQty,Prog_Cns.NoofPiece  UNION ALL SELECT Prog_ClrComb.Yd, Prog_ClrComb.compID, Prog_ClrComb.ID, Prog_ClrComb.ClrCombID, Prog_ClrComb.Fincol, Prog_ClrComb.FabDesc, Prog_ClrComb.GreyGsm, Prog_ClrComb.FinalGsm, Prog_ClrComb.GG, Prog_ClrComb.LL, Prog_Cns.FABWIDTH AS FabWid, Prog_ClrComb.WtUom, Prog_ClrComb.LooseFab, Prog_Cns.sizid, Prog_Cns.Actpcswgt, Prog_Cns.kdia, Prog_Cns.fdia, Prog_Cns.ldia, Sum(Trs_ProdentryQty.ProdPcs) AS OrderQty, 0 AS Exs_Per, Prog_ClrComb.CompGrdSlno,  Prog_ClrComb.PExc, ISNULL(Prog_Cns.NoofPiece, 1) AS NoofPiece, ISNULL(OrderQtyDtl.CutPlanQty, 0)AS CutPlanQty FROM Prog_ClrComb INNER JOIN Prog_Cns ON Prog_ClrComb.ID = Prog_Cns.ID INNER JOIN OrderQtyDtl ON Prog_ClrComb.OrdID = OrderQtyDtl.OrdID AND Prog_ClrComb.StyleNo = OrderQtyDtl.StyleNo AND Prog_Cns.sizid = OrderQtyDtl.SizeId AND Prog_ClrComb.ClrCombID = OrderQtyDtl.ColID  inner join Trs_Prodentry on Trs_Prodentry .ordid =OrderQtyDtl.OrdID  AND Trs_Prodentry.StyleNo = OrderQtyDtl.StyleNo and Trs_Prodentry.clrid = OrderQtyDtl.ColID  inner join Trs_ProdentryQty on Trs_Prodentry.id=Trs_ProdentryQty.id and Trs_ProdentryQty.Sizid = OrderQtyDtl.SizeId   LEFT OUTER JOIN Prog_Component ON Prog_ClrComb.OrdID = Prog_Component.OrdID AND Prog_ClrComb.StyleNo = Prog_Component.StyleNo AND Prog_ClrComb.compID = Prog_Component.CompID AND Prog_ClrComb.ID = Prog_Component.sl INNER JOIN  (Select Distinct A.Ordid,A.Styleno,Stocktable.FabId,StockTable.Colid,StockTable.gsm,stocktable.fingsm,stocktable.gg,stocktable.ll From TRS_Del2 A  INNER JOIN Trs_Del1 B ON A.ID = B.ID  INNER JOIN StockTable ON Stocktable.Stockid = A.StockId Where TrType = -2 and Prs_Dept=11  and stocktable.YF='F' ) X ON X.FabID = Prog_ClrComb.FabDesc And X.colid = prog_clrcomb.fincol And X.gsm = Prog_ClrComb.GreyGsm And X.FinGsm = Prog_ClrComb.FinalGsm and X.GG = Prog_ClrComb.GG  And X.LL = Prog_ClrComb.LL and X.ordid = OrderQtyDtl.Ordid and x.styleno = OrderQtyDtl.Styleno   WHERE     (Prog_ClrComb.OrdID = @OrdId) AND (Prog_ClrComb.StyleNo =  @StyleNo) and Trs_Prodentry.stageid=@StageID and Trs_Prodentry.coyid= @Coycode and Prog_ClrComb.yd = 1 group by Prog_ClrComb.Yd, Prog_ClrComb.compID, Prog_ClrComb.ID, Prog_ClrComb.ClrCombID, Prog_ClrComb.Fincol, Prog_ClrComb.FabDesc, Prog_ClrComb.GreyGsm, Prog_ClrComb.FinalGsm, Prog_ClrComb.GG, Prog_ClrComb.LL, Prog_Cns.FABWIDTH , Prog_ClrComb.WtUom, Prog_ClrComb.LooseFab, Prog_Cns.sizid, Prog_Cns.Actpcswgt, Prog_Cns.kdia, Prog_Cns.fdia, Prog_Cns.ldia,  Prog_ClrComb.CompGrdSlno, Prog_ClrComb.PExc,OrderQtyDtl.CutPlanQty,Prog_Cns.NoofPiece ORDER BY Prog_ClrComb.compID